def solve(I):
    H,W=len(I),len(I[0])
    from collections import Counter
    cnt=Counter(x for row in I for x in row)
    bg=cnt.most_common(1)[0][0]
    comps=[];seen=set()
    for p in [(r,c) for r in range(H) for c in range(W) if I[r][c]!=bg]:
        if p in seen: continue
        st=[p];comp=[]
        while st:
            q=st.pop()
            if q in seen: continue
            seen.add(q);comp.append(q)
            r_,c_=q
            for dr in(-1,0,1):
                for dc in(-1,0,1):
                    nr,nc=r_+dr,c_+dc
                    if 0<=nr<H and 0<=nc<W and I[nr][nc]!=bg and (nr,nc) not in seen: st.append((nr,nc))
        comps.append(comp)
    comp=max(comps,key=len)
    cells=[p for comp2 in comps for p in comp2 if p not in set(comp)]
    pr=min(p[0] for p in comp); pc=min(p[1] for p in comp)
    ph=max(p[0] for p in comp)-pr+1; pw=max(p[1] for p in comp)-pc+1
    P=[[I[pr+i][pc+j] for j in range(pw)] for i in range(ph)]
    out=[row[:] for row in I]
    for (mr,mc) in cells:
        tr=mr-ph//2; tc=mc-pw//2
        for i in range(ph):
            for j in range(pw):
                rr,cc=tr+i,tc+j
                if 0<=rr<H and 0<=cc<W and P[i][j]!=bg: out[rr][cc]=P[i][j]
    return out,P
